function parseBusinessValues(value,current=[]){
 if(value===undefined)return Array.isArray(current)?current:[];const input=String(value??'').trim();if(!input)return [];
 const out=[];for(const raw of input.split(/[，,\n]/).map(x=>x.trim()).filter(Boolean)){
  const text=raw.replace(/^"|"$/g,'');if(/^true$/i.test(text))out.push(true,text);else if(/^false$/i.test(text))out.push(false,text);else if(/^-?(?:0|[1-9]\d*)(?:\.\d+)?$/.test(text))out.push(Number(text),text);else out.push(text);
 }
 return out.filter((item,index,list)=>list.findIndex(other=>JSON.stringify(other)===JSON.stringify(item))===index);
}
