function parseKeyValueLines(value){const out={};for(const line of String(value||'').split('\n')){const text=line.trim();if(!text)continue;const at=text.indexOf('=');if(at<1||at===text.length-1)throw Error('组织编码对应每行应为“学校编码=本地编码”');const key=text.slice(0,at).trim(),item=text.slice(at+1).trim();if(!/^[A-Za-z0-9_.:-]{1,80}$/.test(key)||!/^[A-Za-z0-9_.:-]{1,80}$/.test(item))throw Error('组织编码只能包含字母、数字、点、横线、下划线或冒号');out[key]=item}return out}
