 if(!can('rules.manage')){const refresh=()=>{panel.dataset.ready='true';panel.innerHTML=`<h3>本次计算范围预览</h3><p>适用周期：${esc(periodName($('#f-period_id')?.value))} · 已选择 ${$$('input[name=person]:checked',form).length} 人</p><p>当前账号没有规则维护权限，生效规则由服务端再次核验；提交后才计算入库，本区不提供数值试算。</p>`};form.addEventListener('change',refresh);form.addEventListener('click',()=>setTimeout(refresh,0));refresh();return}
