let qualificationPreviewObserver=null;
function bindQualificationPreviews(root=$('#content')){
 qualificationPreviewObserver?.disconnect();qualificationPreviewObserver=null;
 const buttons=$$('[data-qualification-preview]',root);if(!buttons.length)return;
 const read=async button=>{
  if(!button.isConnected)return;
  const count=button.closest('.qualification-certificate').querySelector('.qualification-image-count'),label=button.querySelector('.qualification-preview-label');
  try{const d=await api('/qualifications/'+button.dataset.id);if(!button.isConnected)return;const images=(d.attachments||[]).filter(isMaterialImage);count.textContent=images.length?images.length+' 张图片 · '+d.attachments.length+' 份材料':d.attachments?.length?'另有 '+d.attachments.length+' 份文档材料':'当前版本暂无材料';
   if(!images.length){label.textContent='暂无图片';button.classList.add('is-empty');button.dataset.action='qualification';button.setAttribute('aria-label','查看材料与历史记录：'+d.qualification.name);return}
   button.setAttribute('aria-label','预览证书图片：'+d.qualification.name+'，共 '+images.length+' 张');const image=button.querySelector('img');image.dataset.materialId=images[0].id;await bindAttachmentPreviews(button);
  }catch{if(button.isConnected)count.textContent='图片暂未读取，点击可重试'}
 };
 // 列表只读取进入视野的证书，按顺序加载；离开页面后不再读取或回填旧行。
 if(typeof IntersectionObserver==='undefined')return buttons.reduce((queue,button)=>queue.then(()=>read(button)),Promise.resolve());
 let queue=Promise.resolve();qualificationPreviewObserver=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){qualificationPreviewObserver?.unobserve(entry.target);queue=queue.then(()=>read(entry.target))}},{rootMargin:'100px'});
 buttons.forEach(button=>qualificationPreviewObserver.observe(button));
}
