function organizationTree(items){
 const seen=new Set();
 const countAll=(item,path=new Set([item.id]))=>{const kids=items.filter(x=>x.parent_id===item.id&&!path.has(x.id));return kids.length+kids.reduce((n,k)=>n+countAll(k,new Set([...path,k.id])),0)};
 const branch=(item,depth=0)=>{if(seen.has(item.id))return '';seen.add(item.id);const children=items.filter(x=>x.parent_id===item.id&&!seen.has(x.id));const has=children.length&&depth<20;
  const toggle=has?`<button type="button" class="org-toggle" data-action="org-toggle" data-id="${esc(item.id)}" aria-expanded="true" aria-label="收起或展开 ${esc(item.name)} 的下级"></button>`:'<span class="org-toggle-gap" aria-hidden="true"></span>';
  const meta=`${esc(roleLevel(item.kind))} · ${esc(item.code)}${has?` · <span class="org-count">下级 ${countAll(item)} 个</span>`:''}`;
  return `<li class="org-node${item.active?'':' is-inactive'}" data-org-node="${esc(item.id)}" data-kind="${esc(item.kind)}"><div class="org-tree-row">${toggle}<span class="org-tree-icon">${icon(item.kind==='school'?'school':'org')}</span><div class="grow"><strong>${esc(item.name)}</strong><p>${meta}</p>${orgHeadsLine(item)}${orgReviewersLine(item)}</div>${badge(item.active?'ACTIVE':'INACTIVE')}<div class="org-tree-actions">${item.heads&&item.active&&can('users.manage')?link('设置负责人','org-head',item.id):''}${item.credit_reviewers&&can('users.manage')?link('设置授课认定人','credit-reviewer',item.id):''}${can('organization.manage')&&item.active?link('编辑','org-form',item.id):''}${can('organization.manage')&&item.kind!=='school'?link(item.active?'停用':'启用','org-state',item.id):''}</div></div>${has?'<ul>'+children.map(x=>branch(x,depth+1)).join('')+'</ul>':''}</li>`};
 const roots=items.filter(x=>!x.parent_id||!items.some(p=>p.id===x.parent_id));let body=roots.map(x=>branch(x)).join('');body+=items.filter(x=>!seen.has(x.id)).map(x=>branch(x)).join('');
 const bar=items.some(x=>items.some(c=>c.parent_id===x.id))?'<div class="org-tree-toolbar"><button type="button" class="btn text" data-action="org-expand-all">全部展开</button><button type="button" class="btn text" data-action="org-collapse-all">全部收起</button></div>':'';
 return body?bar+`<ul class="org-tree" aria-label="组织层级">${body}</ul>`:empty('尚无可见组织','请联系学校管理员核对组织配置。');
}
