async function api(path,{method='GET',body,raw=false,key,headers:providedHeaders={}}={}){
 const headers={...providedHeaders};if(method!=='GET'){headers['X-CSRF-Token']=csrf;if(method!=='DELETE')headers['Idempotency-Key']=key||requestKey()}
 const isBlob=typeof Blob!=='undefined'&&body instanceof Blob;
 if(body!==undefined&&!(body instanceof FormData)&&!isBlob){headers['Content-Type']='application/json';body=JSON.stringify(body)}
 let response;try{response=await fetch('/api'+path,{method,body,headers,credentials:'same-origin',cache:'no-store'})}catch{throw Error('网络连接中断。请检查学校网络后刷新；不要重复确认未知结果。')}
 if(!response.ok){let data;try{data=await response.json()}catch{data={detail:'服务暂不可用'}}
  if(response.status===401&&path!=='/auth/login'){me=null;loginView('登录已失效，请重新登录');closeModal()}
  const detail=typeof data.detail==='object'&&data.detail?data.detail:null,message=typeof data.detail==='string'&&/[\u4e00-\u9fff]/.test(data.detail)?data.detail:detail?.message||'请求未完成，请核对输入或联系管理员';
  const error=Error(message+(Array.isArray(detail?.issues)?'：'+detail.issues.join('、'):'')+(Array.isArray(data.errors)?'\n'+data.errors.map(validationMessage).join('\n'):''));error.requestId=data.request_id||'';error.status=response.status;error.fields=(data.errors||[]).map(x=>String(x.field||''));throw error;}
 return raw?response:response.json();
}
function validationMessage(error){
 const names={name:'名称',reason:'办理意见',basis:'依据说明',period_id:'适用周期',teacher_id:'教师',target_ids:'考核对象',teacher_ids:'教师范围',weight:'权重',target:'目标值',factor:'计算系数',cap:'上限',label:'指标名称',metric:'数据来源',config:'指标配置',components:'指标配置',start_date:'开始日期',end_date:'结束日期',event_date:'业务日期',obtained:'取得日期',expires:'有效期',amount:'调整数值',hours:'学时',income:'收入',participants:'人次',title:'标题',body:'通知内容',password:'密码',username:'账号',email:'邮箱',staff_no:'工号',org_id:'所属组织',item_keys:'积分项目',expected_version:'数据版本',calendar_start:'校历开始日期',calendar_end:'校历结束日期',calendar_reference:'校历依据',interpretation_reference:'学校书面依据',self_report:'自评报告',policy_id:'制度口径',source:'学校来源字段',transform:'转换方式',page_size:'每次读取数量',max_pages:'最多读取页数',endpoint:'学校接口地址',owner:'责任单位',secret_env:'服务器凭据引用',draft_version:'待发布资料版本'};
 const parts=String(error.field||'').split('.').filter(x=>!['body','query','path'].includes(x));const last=parts.at(-1);const fieldLabel=/^[A-Za-z_][A-Za-z0-9_]*$/.test(last||'')?$('#f-'+last)?.labels?.[0]?.textContent?.replace(/\*/g,'').trim():'';const row=parts.find(x=>/^\d+$/.test(x)),type=parts.find(x=>integrationTypeNames[x]);const name=(type?integrationTypeNames[type]+' · ':'')+(row!==undefined?'第'+(Number(row)+1)+'行 · ':'')+(fieldLabel||names[last]||'表单内容');const msg=String(error.message||'');
 const chinese=msg.replace(/^Value error,\s*/,'');if(/^[\u4e00-\u9fff]/.test(chinese))return name+'：'+chinese;
 if(/required/i.test(msg))return name+'：请填写此项';
 const limit=msg.match(/(at least|at most|greater than or equal to|less than or equal to)\s+(\d+(?:\.\d+)?)/i);
 if(limit){const prefix=/at least/i.test(limit[1])?'至少需要':/at most/i.test(limit[1])?'不能超过':/greater/i.test(limit[1])?'不能小于':'不能大于';return name+'：'+prefix+limit[2]+(/characters/i.test(msg)?'个字符':/items/i.test(msg)?'项':'');}
 if(/number|integer|decimal/i.test(msg))return name+'：请输入有效数字';
 if(/date/i.test(msg))return name+'：请输入有效日期';
 return name+'：格式或取值不符合要求，请检查后重新提交';
}
// 后端报错本来就是中文；浏览器里的英文技术报错（如 Cannot read properties of undefined）不直接给用户看。
const friendlyError=err=>{const m=String(err?.message??err??'');if(/[\u4e00-\u9fff]/.test(m))return m;console.error(err);return '这一页暂时没加载出来，请点“重新读取”或刷新页面；还不行请联系管理员。'+(err?.requestId?`（请求编号 ${err.requestId}）`:'')};
function toast(message,error=false){if(error)message=friendlyError({message});const root=$('#toasts');const live=()=>Array.from(root.children||[]);live().forEach(x=>{if(x.dataset?.msg===message)x.remove()});if(!error)live().forEach(x=>{if(x.classList?.contains('error'))x.remove()});while(live().length>=3)live()[0].remove();const el=document.createElement('div');el.className='toast'+(error?' error':'');if(el.dataset)el.dataset.msg=message;el.setAttribute?.('role',error?'alert':'status');const text=document.createElement('span');text.className='toast-text';text.textContent=message;const close=document.createElement('button');close.type='button';close.className='toast-close';close.setAttribute?.('aria-label','关闭提示');close.textContent='×';close.addEventListener?.('click',()=>el.remove());el.append(text,close);root.append(el);setTimeout(()=>el.remove(),error?9000:5000)}
function field(name,label,type='text',value='',opts={}){
 const attrs=`id="f-${name}" name="${name}" ${opts.required===false?'':'required'} ${opts.readonly?'readonly':''} ${opts.min!==undefined?`min="${opts.min}"`:''} ${opts.max!==undefined?`max="${opts.max}"`:''} ${opts.step?`step="${opts.step}"`:''} ${opts.placeholder?`placeholder="${esc(opts.placeholder)}"`:''}`;
 let input;if(type==='select'&&opts.chips){const list=(opts.options||[]).map(o=>Array.isArray(o)?o:[o,o]).filter(([v])=>String(v)!=='');input=`<div class="choice-row" id="f-${name}" role="radiogroup" aria-label="${esc(label)}">${list.map(([v,l],i)=>`<label class="choice"><input type="radio" name="${name}" value="${esc(v)}" ${String(v)===String(value)?'checked':''} ${i===0&&opts.required!==false?'required':''}><span>${esc(l)}</span></label>`).join('')}</div>`}
 else if(type==='select')input=`<select ${attrs}>${(opts.options||[]).map(o=>{let [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`}).join('')}</select>`;
 else if(type==='textarea')input=`<textarea ${attrs} rows="${opts.rows||3}">${esc(value)}</textarea>`;
 else if(type==='checkbox')input=`<label class="flex"><input id="f-${name}" name="${name}" type="checkbox" ${value?'checked':''}>${esc(opts.checkLabel||'启用')}</label>`;
 else input=`<input type="${type}" ${attrs} value="${esc(value)}" ${opts.accept?`accept="${opts.accept}"`:''} ${type==='file'&&opts.multiple?'multiple':''} ${type==='password'?'autocomplete="new-password"':''}>`;
 return `<div class="form-field ${opts.full||(type==='select'&&opts.chips)?'full':''}"><label for="f-${name}">${esc(label)}${opts.required===false||type==='checkbox'?'':' <b>*</b>'}</label>${input}${opts.hint?`<p class="hint">${esc(opts.hint)}</p>`:''}</div>`;
}
