const isMaterialImage=file=>/\.(png|jpe?g)$/i.test(file.name||'');
function readMaterialImage(blob){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('图片读取失败，请重新选择或下载查看。'));reader.readAsDataURL(blob)})}
async function materialThumbnail(blob){
 const source=await readMaterialImage(blob),image=new Image();image.src=source;await image.decode();
 const canvas=document.createElement('canvas'),scale=Math.min(1,320/image.width,240/image.height);canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/png');
}
function openMaterialPreview(items,start,load,save=null){
 const trigger=actionTrigger?.isConnected?actionTrigger:document.activeElement,dialog=document.createElement('dialog');dialog.className='material-viewer';dialog.setAttribute('aria-label','图片材料预览');
 dialog.innerHTML='<header><div><p>图片材料预览</p><h2 id="material-preview-name"></h2></div><button type="button" class="btn" data-preview-close aria-label="关闭图片预览">关闭预览</button></header><div class="material-viewer-stage"><p role="status"></p><img alt="" hidden></div><footer><button type="button" class="btn" data-preview-prev>上一张</button><span aria-live="polite"></span><button type="button" class="btn" data-preview-next>下一张</button><button type="button" class="btn" data-preview-zoom>查看原图</button><button type="button" class="btn primary" data-preview-save>下载原图</button></footer>';
 const stage=dialog.querySelector('.material-viewer-stage'),image=stage.querySelector('img'),status=stage.querySelector('p'),previous=dialog.querySelector('[data-preview-prev]'),next=dialog.querySelector('[data-preview-next]'),zoom=dialog.querySelector('[data-preview-zoom]'),downloadButton=dialog.querySelector('[data-preview-save]');let index=start,sequence=0;
 const show=async at=>{index=at;const current=++sequence,item=items[index];image.hidden=true;image.removeAttribute('src');stage.classList.remove('is-zoomed');zoom.textContent='查看原图';zoom.disabled=true;downloadButton.disabled=!save;status.textContent='正在读取图片…';dialog.querySelector('h2').textContent=item.name;dialog.querySelector('footer span').textContent=(index+1)+' / '+items.length;previous.disabled=index===0;next.disabled=index===items.length-1;
  try{const source=await readMaterialImage(await load(item));if(current!==sequence||!dialog.isConnected)return;image.src=source;image.alt=item.name;await image.decode();if(current!==sequence||!dialog.isConnected)return;status.textContent='';image.hidden=false;zoom.disabled=false;downloadButton.disabled=false}
  catch{if(current===sequence&&dialog.isConnected)status.textContent='图片暂时无法预览，请检查文件或下载查看。'}
 };
 dialog.querySelector('[data-preview-close]').addEventListener('click',()=>dialog.close());previous.addEventListener('click',()=>show(index-1));next.addEventListener('click',()=>show(index+1));zoom.addEventListener('click',()=>{const expanded=stage.classList.toggle('is-zoomed');zoom.textContent=expanded?'适应窗口':'查看原图'});
 downloadButton.hidden=!save;downloadButton.addEventListener('click',async()=>{try{await save(items[index])}catch(err){toast(err.message,true)}});
 dialog.addEventListener('keydown',event=>{event.stopPropagation();if(event.target===dialog||event.target.tagName==='BUTTON'){if(event.key==='ArrowLeft'&&index>0){event.preventDefault();show(index-1)}if(event.key==='ArrowRight'&&index<items.length-1){event.preventDefault();show(index+1)}}});
 dialog.addEventListener('close',()=>{sequence++;image.removeAttribute('src');dialog.remove();if(trigger?.isConnected&&!trigger.disabled)trigger.focus({preventScroll:true})},{once:true});document.body.append(dialog);dialog.showModal();show(start);
}
function bindFileFeedback(form){
 $$('input[type=file]',form).forEach((input,index)=>{
  const status=document.createElement('p');status.className='file-selection-status';status.id=(input.id||'file-'+index)+'-selection';status.setAttribute('role','status');
  const previews=document.createElement('div');previews.className='material-selection';previews.setAttribute('aria-label','已选材料预览');input.insertAdjacentElement('afterend',previews);input.insertAdjacentElement('afterend',status);
  input.setAttribute('aria-describedby',[input.getAttribute('aria-describedby'),status.id].filter(Boolean).join(' '));let selection=0;
  const update=async()=>{const current=++selection,files=Array.from(input.files||[]),images=files.filter(file=>isMaterialImage(file)&&file.size<=10*1024*1024);status.textContent=files.length?`已选择 ${files.length} 份文件。图片可点击放大，确认后再保存或上传。`:input.multiple?'尚未选择文件。可一次选择多张图片或多份材料。':'尚未选择文件。选择后请核对文件名，再保存或上传。';previews.replaceChildren();
   for(const file of files){if(current!==selection||!input.isConnected)return;const card=document.createElement('div');card.className='material-selection-item';const button=document.createElement('button');button.type='button';button.className='material-selection-thumb';button.setAttribute('aria-label',isMaterialImage(file)?'预览 '+file.name:'文档 '+file.name);button.disabled=!isMaterialImage(file);button.textContent=isMaterialImage(file)?'正在读取…':'文档';const name=document.createElement('strong');name.textContent=file.name;const size=document.createElement('small');size.textContent=number(file.size/1024,1)+' 千字节';card.append(button,name,size);
    if(input.multiple){const remove=document.createElement('button');remove.type='button';remove.className='btn sm text';remove.textContent='移除';remove.setAttribute('aria-label','移除 '+file.name);remove.addEventListener('click',()=>{const transfer=new DataTransfer();Array.from(input.files).filter(item=>item!==file).forEach(item=>transfer.items.add(item));input.files=transfer.files;input.dispatchEvent(new Event('change',{bubbles:true}))});card.append(remove)}
    previews.append(card);if(!isMaterialImage(file))continue;if(file.size>10*1024*1024){button.textContent='超过 10 兆字节';button.disabled=true;continue}button.addEventListener('click',()=>openMaterialPreview(images,images.indexOf(file),async item=>item));
    try{const source=await materialThumbnail(file);if(current!==selection||!input.isConnected)return;const img=document.createElement('img');img.src=source;img.alt=file.name;button.replaceChildren(img)}catch{button.textContent='图片无法预览';button.disabled=true}
   }
  };
  input.addEventListener('change',update);update();
 });
}
