function modal(title,body,foot='',wide=false,contextLabel=''){if($('#modal-root').classList.contains('hidden'))modalTrigger=actionTrigger?.isConnected?actionTrigger:document.activeElement;$('#modal-root').innerHTML=`<section role="dialog" aria-modal="true" aria-label="${esc(title)}" class="modal ${wide?'wide':''}"><header class="modal-head"><div><p class="detail-location">${esc(contextLabel||pageTitle(page)+' / 详情与办理')}</p><h2>${esc(title)}</h2></div>${act('','close','','icon-btn','close')}</header><div class="modal-body">${body}</div><footer class="modal-foot"><span class="foot-note"></span>${foot||act('关闭','close')}</footer></section>`;$('#modal-root').classList.remove('hidden');bindDetailSections($('#modal-root'));bindAttachmentPreviews($('#modal-root'));const more=$('#modal-root .detail-more-actions');more?.addEventListener('keydown',event=>{if(event.key==='Escape'){more.open=false;more.querySelector('summary')?.focus();event.stopPropagation()}});setTimeout(()=>$$('input:not([type=hidden]),textarea,select,button',$('#modal-root')).find(el=>el.getClientRects().length&&!el.disabled)?.focus(),30)}
function bindFormSteps(form,submitLabel,partialDraft){
 const groups=$$('.social-fieldset, .integration-form-section',form);if(groups.length<3)return null;
 const extra=groups.at(-1).querySelector('legend')?.textContent==='办理说明'?groups.pop():null;
 const nav=document.createElement('nav');nav.className='form-step-nav';nav.setAttribute('aria-label','填写步骤');
 const title=g=>(g.querySelector('legend')||g.querySelector('h3'))?.textContent?.replace(/^[一二三四五六七八九十]+、\s*/,'')||'填写内容';
 nav.innerHTML=groups.map((g,i)=>`<button type="button" class="btn sm" data-form-step="${i}">${i+1} · ${esc(title(g))}</button>`).join('');form.prepend(nav);form.noValidate=true;
 const foot=$('#modal-root .modal-foot'),previous=document.createElement('button');previous.type='button';previous.className='btn';previous.textContent='上一步';foot.prepend(previous);
 const submits=$$('button[type=submit][form=edit-form]');let draft=null,current=0;
 if(partialDraft){draft=document.createElement('button');draft.type='submit';draft.setAttribute('form','edit-form');draft.dataset.partialDraft='true';draft.className='btn';draft.textContent='保存草稿';foot.insertBefore(draft,submits[0]);}
 const show=n=>{current=n;groups.forEach((g,i)=>{g.hidden=i!==n});if(extra)extra.hidden=n!==groups.length-1;previous.hidden=n===0;if(draft)draft.hidden=n===groups.length-1;submits.forEach(b=>b.textContent=n===groups.length-1?submitLabel:'下一步');$$('button',nav).forEach((b,i)=>{b.classList.toggle('primary',i===n);b.setAttribute('aria-current',i===n?'step':'false')});};
 const reveal=el=>{const index=groups.findIndex(g=>g.contains(el));show(index<0?groups.length-1:index);let parent=el.parentElement;while(parent&&parent!==form){if(parent.tagName==='DETAILS')parent.open=true;parent=parent.parentElement;}};
 const validate=elements=>{const invalid=elements.find(el=>el.willValidate&&!el.checkValidity());if(!invalid)return true;reveal(invalid);const label=invalid.labels?.[0]?.textContent?.replace(/\*/g,'').trim()||'当前填写项';$('#form-error').innerHTML=`<div class="error-text">${esc(label)}：请按要求填写，其他已填内容保留。</div>`;invalid.reportValidity();return false;};
 previous.addEventListener('click',()=>show(current-1));nav.addEventListener('click',e=>{const button=e.target.closest('[data-form-step]');if(button)show(Number(button.dataset.formStep))});show(0);
 return {reveal,submit(button){$('#form-error').innerHTML='';if(button?.dataset.partialDraft==='true')return validate($$('input,select,textarea',form));if(current<groups.length-1){if(validate($$('input,select,textarea',groups[current])))show(current+1);return false;}return validate($$('input,select,textarea',form));}};
}
