function filtersBar({search=true,states=[],period=false,dates=false,teacher=false,organization=false,project=false,returned=false,exportKind=''}={}){
 const advancedKeys=['start','end','teacher_id','project_code','course_code','returned'];
 const activeAdvanced=advancedKeys.some(k=>filter[k]);
 const searchHint=['records','cockpit','organization','home'].includes(page)?(me.role.kind==='teacher'?'项目或课程名称':'教师姓名、工号、项目或课程'):'搜索名称或编号';
 const advanced=(returned?`<label>退回状态<select name="returned"><option value="">全部退回状态</option><option value="true" ${filter.returned==='true'?'selected':''}>已退回</option><option value="false" ${filter.returned==='false'?'selected':''}>未退回</option></select></label>`:'')+(dates?`<label>开始日期<input name="start" type="date" value="${esc(filter.start||'')}"></label><label>结束日期<input name="end" type="date" value="${esc(filter.end||'')}"></label>`:'')+(teacher?`<label>教师工号<input class="filter-teacher" name="teacher_search" list="filter-teacher-list" placeholder="检索授权教师工号" value="${esc(teachers.find(t=>t.id===filter.teacher_id)?.staff_no||'')}"><datalist id="filter-teacher-list">${teachers.map(t=>`<option value="${esc(t.staff_no)}">${esc(t.name)}</option>`).join('')}</datalist></label>`:'')+(project?`<label>项目编码<input name="project_code" placeholder="输入项目编码" value="${esc(filter.project_code||'')}"></label><label>课程编码<input name="course_code" placeholder="输入课程编码" value="${esc(filter.course_code||'')}"></label>`:'');
 return `<form id="filters" class="filterbar filter-panel"><div class="filter-primary">${search?`<label class="filter-keyword">关键词<div class="field-search">${icon('search')}<input name="q" aria-label="${searchHint}" placeholder="${searchHint}" value="${esc(filter.q||'')}"></div></label>`:''}${period?`<label>统计周期${periodSelect()}</label>`:''}${states.length?`<label>办理状态<select name="state"><option value="">全部状态</option>${states.map(s=>`<option value="${s}" ${filter.state===s?'selected':''}>${labels[s]||'待核对状态'}</option>`).join('')}</select></label>`:''}${organization?`<label>所属组织<select name="org_id"><option value="">全部授权组织</option>${orgs.filter(o=>o.kind!=='school').map(o=>`<option value="${o.id}" ${filter.org_id===o.id?'selected':''}>${esc(o.name)}</option>`).join('')}</select></label>`:''}<div class="filter-actions"><button class="btn primary" type="submit">查询</button>${act('重置','reset-filters')}${exportKind&&can('export')?act('导出表格','export',exportKind,'','export'):''}</div></div>${advanced?`<details class="advanced-filters" ${activeAdvanced?'open':''}><summary>更多筛选${activeAdvanced?' · 有条件生效':''}</summary><div class="filter-advanced-grid">${advanced}</div></details>`:''}${filterSummary()}</form>`;
}
function filterSummary(){
 const names={q:'关键词',org_id:'组织',teacher_id:'教师',start:'开始日期',end:'结束日期',project_code:'项目编码',course_code:'课程编码',state:'状态',returned:'退回情况',business_scope:'明细范围',progress:'进度'};
 const pairs=Object.entries(filter).filter(([key,value])=>names[key]&&value!==''&&value!=null);
 if(!pairs.length&&!periodId)return '';
 const value=(key,v)=>key==='org_id'?orgName(v):key==='teacher_id'?teacherName(v):key==='state'?(labels[v]||'待核对状态'):key==='returned'?(v==='true'?'已退回':'未退回'):key==='business_scope'?'来源业务穿透':key==='progress'?({pending:'本级待处理',done:'本级已完成',returned:'已退回'}[v]||v):v;
 return '<div class="filter-applied" aria-label="已生效筛选">'+(periodId?'<span>周期：'+esc(periodName(periodId))+'</span>':'')+pairs.map(([k,v])=>'<span>'+names[k]+'：'+esc(value(k,v))+'</span>').join('')+'</div>';
}
