async function boot(){
 const data=await api('/auth/me');me=data;csrf=data.csrf;document.body.dataset.role=data.role?.kind||'';
 if(me.user.must_change_password){shell();$('#content').innerHTML=pageHead('首次使用前，请修改管理员分配的临时密码。');changePassword(true);return}
 const loaded=await Promise.all([api('/periods'),loadAllTeachers(),api('/organizations'),api('/dictionaries'),loadCodeTables(api)]);
 periods=loaded[0].items;teachers=loaded[1].items;orgs=loaded[2].items;businessConfig=loaded[3];Object.assign(labels,businessConfig.status_labels||{});
 let restored;try{restored=restoreNavigation(location.hash,titles)}catch{location.hash='';restored=restoreNavigation('',titles)}/* 地址栏筛选参数写坏时回到首页，不让登录后白屏 */
 page=routeAlias(restored.page);filter=restored.filter;periodId=restored.periodId;
 let scopeChanged=false;if(!pageAllowed(page)){scopeChanged=page!=='home';page='home';filter={};periodId=''}
 // 老师登录后落在菜单第一项“工作总览”（要处理的事、我的申请、我的超星课都在这里）。
 shell();mountAccountMenu();await render();
 if(scopeChanged)toast('原页面不在当前身份的授权范围内，已回到工作总览。');
}
// 共用已有身份授权；这里只呈现角色、待办数量和原账号操作。
let accountRefreshTimer=null,accountSummaryLoading=false;
function accountRoleItems(){
 const demo=me?.demo_switch;
 return [...(demo?.options||[]).map(x=>({...x,key:'demo:'+x.username,label:x.label,current:x.username===demo.current,kind:({teacher:'teacher',show_teacher:'teacher',depthead:'dept',show_dept:'dept',collegehead:'college',show_college:'college'})[x.username]||'school'})),
  ...(me?.identities||[]).map(x=>({...x,key:'identity:'+x.id,label:x.role_name,detail:x.org_name,kind:x.role_kind}))];
}
function accountOtherTodos(){return accountRoleItems().filter(x=>!x.current).reduce((n,x)=>n+(Number.isFinite(x.todo_count)&&x.todo_count>0?x.todo_count:0),0)}
function accountRoleRows(){
 return accountRoleItems().map(x=>`<button type="button" class="account-role-row${x.current?' is-current':''}" data-action="account-switch" data-id="${esc(x.key)}" ${x.unavailable?'disabled':''} ${x.current?'aria-current="true"':''}>${icon(({teacher:'users',dept:'users',college:'school',school:'shield'})[x.kind]||'users')}<span class="account-role-copy"><strong>${esc(x.label)}</strong>${x.detail?`<small>${esc(x.detail)}</small>`:''}</span>${Number.isFinite(x.todo_count)&&x.todo_count>0?`<span class="account-count" aria-label="${x.todo_count} 项待办">${x.todo_count>99?'99+':x.todo_count}</span>`:''}${x.unavailable?'<small>不可用</small>':x.current?'<span class="account-selected">'+icon('check')+'</span>':''}</button>`).join('')||`<p class="account-single-role">当前角色：${esc(me?.role?.name||'')}</p>`;
}
function accountMenuHtml(){
 const count=accountOtherTodos();
 return `<div class="nd-header__identity"><span class="nd-header__avatar" aria-hidden="true">${esc(me.user.name.slice(0,1))}</span><div class="nd-header__person current-identity" title="${esc(me.user.name+' · '+me.role.name)}"><strong>${esc(me.user.name)}</strong><small>${esc(me.role.name)}</small></div><details class="account-menu" id="account-menu"><summary class="account-trigger" aria-label="切换角色" aria-controls="account-panel">${icon('sync')}<span>切换角色</span>${icon('down')}<span id="account-other-alert" class="account-count" title="其他角色待办" ${count?'':'hidden'}>${count>99?'99+':count||''}</span></summary><section class="account-panel" id="account-panel" aria-label="账号与角色"><div class="account-panel-heading"><h2>${me.demo_switch?'选择演示角色':me.identities?.length?'选择办理身份':'账号信息'}</h2><span class="account-other-total" id="account-total-label" ${count?'':'hidden'}>其他角色待办 <b id="account-menu-total">${count>99?'99+':count}</b></span></div><div id="account-role-list">${accountRoleRows()}</div><p class="account-panel-hint">${accountRoleItems().length?'有红色数字的角色有待办，点击可切换处理。':'查看本人账号资料与密码设置。'}</p><p id="account-count-status" class="account-count-status" role="status"></p><footer class="account-panel-footer">${act('账号信息','profile','','text','users')}${act('修改密码','password','','text','lock')}</footer></section></details></div>`;
}
async function refreshAccountSummary(){
 if(!me||me.user.must_change_password||accountSummaryLoading)return;
 const owner=me;accountSummaryLoading=true;
 try{
  const data=await api('/auth/role-summary');if(me!==owner)return;
  const selection=x=>[x.demo_switch?.current||'',(x.identities||[]).find(y=>y.current)?.id||''].join('|');
  if(selection(data)!==selection(owner)){const status=$('#account-count-status');if(status)status.textContent='登录身份已变化，请刷新页面后重试。';return;}
  me.demo_switch=data.demo_switch;me.identities=data.identities||[];
  const rows=$('#account-role-list');if(rows)rows.innerHTML=accountRoleRows();
  const other=accountOtherTodos(),badge=$('#account-other-alert');if(badge){badge.hidden=!other;badge.textContent=other>99?'99+':String(other);badge.title='其他角色共 '+other+' 项待办';badge.setAttribute('aria-label',badge.title)}
  const total=$('#account-menu-total');if(total)total.textContent=other>99?'99+':String(other);const totalLabel=$('#account-total-label');if(totalLabel)totalLabel.hidden=!other;
  const current=data.current_todo_count,bell=$('#header-todo-count');if(bell){bell.hidden=!(current>0);bell.textContent=current>99?'99+':String(current||0);bell.setAttribute('aria-label','当前角色 '+(current||0)+' 项待办');const tip=me.role.kind==='teacher'?'待办：需要本人办理的事项':'待办：本级审批事项，另含安全提示、接口失败等系统提醒';bell.parentElement?.setAttribute?.('title',tip)}
  const status=$('#account-count-status');if(status)status.textContent=accountRoleItems().some(x=>x.unavailable)?'部分身份暂不可用，请联系管理员核对。':'';
 }catch(err){if(me===owner){const status=$('#account-count-status');if(status)status.textContent='待办数量暂未读取，请收起后重新打开。'}}
 finally{accountSummaryLoading=false}
}
function mountAccountMenu(){
 const menu=$('#account-menu');if(!menu)return;
 menu.addEventListener('toggle',()=>{if(menu.open)refreshAccountSummary()});refreshAccountSummary();
 if(!accountRefreshTimer&&typeof window.setInterval==='function')accountRefreshTimer=window.setInterval(()=>{if(me&&!document.hidden)refreshAccountSummary()},60000);
}
let accountSwitching=false;
// 切换身份后留在同一业务：只保留业务页和页签，教师、组织、关键词等查询条件一律清除，新身份无权时由 boot 回到工作总览。
async function switchAccountRole(key){
 const item=accountRoleItems().find(x=>x.key===key);if(!item||item.unavailable)throw Error('当前身份不可用，请刷新后重试。');
 if(item.current){$('#account-menu').open=false;return}
 if(accountSwitching)return;
 if(document.querySelector?.('.modal form')&&window.confirm?.('当前窗口里有未保存的内容，切换身份后会丢失。确定要切换吗？')===false)return;
 accountSwitching=true;
 const demo=key.startsWith('demo:');
 try{await api(demo?'/auth/demo-switch':'/auth/identity',{method:'POST',body:demo?{username:item.username}:{identity_id:item.id}})}finally{accountSwitching=false}
 $('#app').innerHTML='<div class="busy-panel" role="status">正在切换身份…</div>';closeModal();
 const keep={};for(const k of ['tab','project_view'])if(filter?.[k])keep[k]=filter[k];
 history.replaceState(null,'',location.pathname+location.search+navigationHash(page,pageFilters(page,keep)));location.reload();
}
