  if(permissionsSection==='organizations')body=`<section class="card"><div class="card-head"><div><h2>学校组织结构</h2><p>学校 → 二级学院 → 教研室；停用不删除历史业务。${vacantOrgNote(orgs)}</p></div></div><div class="card-pad">${organizationTree(orgs)}</div></section>`;
  if(permissionsSection==='roles')body=`<section class="card"><div class="card-head"><div><h2>角色与批量授权</h2><p>角色决定可做的操作，组织决定可查看的数据范围。</p></div></div>${table(['角色','管理层级','数据范围','权限数','状态','操作'],r.items.map(x=>[esc(x.name),esc(roleLevel(x.kind)),esc(roleScope(x.kind)),x.permissions.length,badge(x.active?'ACTIVE':'INACTIVE'),link('批量授权','role-permissions',x.id)+link('复制角色','role-copy',x.id)]))}</section>`;
