function bindRecordReferences(){
 const form=$('#edit-form'),specs=[['project_code','project','projects'],['course_code','course','courses'],['class_code','class_name','classes']];
 const controls=specs.filter(([key])=>$('#f-'+key)).map(([key,name,endpoint])=>{
  const input=$('#f-'+key),target=$('#f-'+name),list=document.createElement('datalist');
  list.id='reference-'+key;form.append(list);input.setAttribute('list',list.id);input.autocomplete='off';
  return {key,input,target,list,endpoint,items:[],sequence:0,timer:null,lastCode:input.value};
 });
 const scope=c=>({...((c.key!=='project_code'&&controls[0].input.value)?{project_code:controls[0].input.value}:{}),...((c.key==='class_code'&&controls[1].input.value)?{course_code:controls[1].input.value}:{})});
 const choose=c=>{const found=c.items.find(row=>row.code===c.input.value);c.target.readOnly=!!found;if(found)c.target.value=found.name};
 const load=async(c,search='')=>{
  const sequence=++c.sequence;
  try{
   const data=await api('/reference/'+c.endpoint+'?'+query({...scope(c),...(search?{q:search}:{}),size:50,...(c.endpoint!=='classes'?{active:true}:{})}));
   if(!form.isConnected||sequence!==c.sequence)return;
   c.items=data.items;c.list.innerHTML=data.items.map(row=>`<option value="${esc(row.code)}">${esc(row.name)}</option>`).join('');choose(c);
   $('#reference-status').textContent=data.total>50?'仅展示前 50 项，请继续输入名称或编号缩小范围。':'选择已有编号后名称自动填写；没有匹配时可按已核实资料补录。';
  }catch{if(form.isConnected&&sequence===c.sequence)$('#reference-status').textContent='主数据检索暂不可用；可取消重试，或按已核实资料填写，保存时仍会校验关联。'}
 };
 controls.forEach((c,index)=>{
  c.input.addEventListener('input',()=>{
   c.sequence++;clearTimeout(c.timer);
   if(c.lastCode!==c.input.value){
    c.lastCode=c.input.value;c.target.value='';
    controls.slice(index+1).forEach(child=>{child.sequence++;clearTimeout(child.timer);child.input.value='';child.lastCode='';child.target.value='';child.target.readOnly=false;child.items=[];child.list.innerHTML='';child.timer=setTimeout(()=>load(child),250)});
   }
   choose(c);c.timer=setTimeout(()=>load(c,c.items.some(x=>x.code===c.input.value)?'':c.input.value),250);
  });
  load(c,c.input.value);
 });
}
