async function printRanking(kind){
 const isOrg=kind==='organization',f=isOrg?orgRankingContext:{...filter,...(periodId?{period_id:periodId}:{})};
 if(isOrg&&!f)throw Error('请先选择可比的组织考核排名范围');
 const d=await api((isOrg?'/organization-assessment-ranking/print?':'/assessment-ranking/print?')+query(f));
 $('.print-sheet')?.remove();const el=document.createElement('section');el.className='print-sheet';
 const heads=isOrg?['名次','组织（生成时）','得分','状态']:['名次','教师','工号','考核周期','得分','当前环节','是否退回'];
 el.innerHTML=`<h1>${isOrg?'组织考核排名表':'教师考核排名表'}</h1><p>学校：${esc(me.school_name||'')}　周期：${esc(f.period_id?periodName(f.period_id):'全部周期')}${isOrg?`　规则：${esc(d.rule_name)} 版本 ${esc(d.rule_version)}`:''}　排名方式：同分并列</p><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${d.items.map(x=>isOrg?`<tr><td>${esc(x.rank)}</td><td>${esc(x.target_name)}</td><td>${number(x.score,2)}</td><td>${esc(labels[x.state]||x.state)}</td></tr>`:`<tr><td>${esc(x.rank)}</td><td>${esc(x.teacher_name)}</td><td>${esc(x.staff_no)}</td><td>${esc(x.period_name)}</td><td>${number(x.score,2)}</td><td>${esc(labels[x.state]||x.state)}</td><td>${x.returned?'是':'否'}</td></tr>`).join('')}</tbody></table><p>${esc(d.note)}　共 ${number(d.total)} 项</p><small>打印人 ${esc(me.user.name)}　时间 ${new Date().toLocaleString('zh-CN')}</small>`;
 document.body.append(el);document.body.classList.add('print-mode');try{window.print()}finally{document.body.classList.remove('print-mode')}
}
function sourceChangesNotice(d){
 const change=d.source_changes;if(!change?.changed)return '';
 return `<section class="source-changes" role="alert"><h3>计算依据已变化，请先核对</h3><p>以下结果仍引用计算时的数据，暂不能向前确认或归档。已审核的结果请先退回，重新取数后再确认。</p>${table(['受影响指标','计算时','当前'],change.items.map(x=>[esc(x.label),esc(x.before),esc(x.after)]))}${change.items.filter(x=>x.details?.length).map(x=>`<details><summary>${esc(x.label)} · 查看变更记录（${x.detail_count||x.details.length} 条）</summary>${table(['业务记录','计算时','当前'],x.details.map(r=>[esc(r.name),esc(r.before),esc(r.after)]))}</details>`).join('')}</section>`;
}
async function recalculateAffected(code){
 const[kind,id]=code.split('|'),path=kind==='organization'?'/organization-assessments/':'/assessments/',d=await api(path+id),x=d.assessment;
 const payload=kind==='organization'?{period_id:x.period_id,target_kind:x.target_kind,target_ids:[x.target_id]}:{period_id:x.period_id,teacher_ids:[x.teacher_id]};
 formModal('重新取数并计算',sourceChangesNotice(d)+reasonFields(),async v=>{
  await api(path+'calculate',{method:'POST',body:{...payload,...v}});
  closeModal();await render();if(kind==='organization')await showOrgAssessment(id);else await showAssessment(id);
 },{submit:'核对后重新计算',hint:'只重算当前对象；重算后需要重新确认，原办理记录保留。涉及积分依据变化时，请先办理积分重算。'});
}
function assessmentBlockerNotice(d,id){
 const b=d.confirmation_blockers;
 if(!b?.count)return '';
 if(me.role.kind==='teacher')return `<section class="teacher-blocker-summary" aria-label="待处理的数据核对"><strong>还有 ${number(b.count)} 项数据待核对</strong><p>核对完成后才能确认考核。你可以查看进度，按需补充材料。</p>${b.can_view?`<details><summary>查看核对事项</summary>${table(['核对原因','提出时间','操作'],b.items.map(x=>[esc(x.reason),ts(x.created_at),act('查看进度','assessment-dispute',x.id+'|'+id,'text')]))}</details>`:'<p>请联系学校管理员安排授权人员核对。</p>'}</section>`;

 return `<section class="assessment-blockers mt16" aria-label="待处理的数据核对">${note('该教师有 '+b.count+' 项数据核对尚未完成，暂不能确认或归档考核。',true)}<p class="small mt12">${b.can_resolve?'请先核实原业务；需要更正时先完成更正或退回重算，再填写复核结论。':'核对申请须由有权限且不是申请人本人的人员复核。可查看处理进度，完成后返回本考核继续办理。'}</p>${b.can_view?table(['业务类型','核对原因','提出时间','操作'],b.items.map(x=>[esc({record:'培训数据',points:'教师积分',assessment:'教师考核'}[x.object_type]||'业务数据'),esc(x.reason),ts(x.created_at),act(b.can_resolve?'查看 / 处理':'查看进度','assessment-dispute',x.id+'|'+id,'sm')])):note('当前账号没有查看核对详情的权限，请联系学校管理员安排复核。')}</section>`;
}
async function showAssessmentBlockers(id){
 const d=await api('/assessments/'+id);
 if(!d.confirmation_blockers?.count){await showAssessment(id);toast('相关数据核对已完成，可以继续办理考核');return}
 modal('先完成数据核对',`<h3>${esc(d.teacher.name)} · ${esc(d.period.name)}</h3>${assessmentBlockerNotice(d,id)}`,act('返回考核详情','assessment',id)+act('刷新核对进度','assessment-blockers',id,'primary','refresh'),true);
}
async function assessmentAction(code){
 const[action,id,then]=code.split('|'),d=await api('/assessments/'+id),x=d.assessment,queued=then==='next'?queueNext('assessment|'+id):'';
 if(['confirm','archive'].includes(action)&&d.confirmation_blockers?.count){await showAssessmentBlockers(id);return}
 if(['confirm','archive'].includes(action)&&d.source_changes?.changed){await showAssessment(id);return}
 const next={TEACHER:'教研室确认',DEPARTMENT:'学院确认',COLLEGE:'学校审核',SCHOOL:'归档准备'};
 const title={confirm:{TEACHER:'本人确认并提交教研室',DEPARTMENT:'确认并提交学院',COLLEGE:'确认并提交学校',SCHOOL:'审核通过，进入归档'}[x.state]||'确认提交',return:'退回教师重新核对',archive:'确认归档结果'}[action];
 const hint=action==='return'?'退回后由教师重新核对；如需更正分值或重算，请由授权人员办理。':action==='archive'?'归档后本次考核结果及依据将冻结，请核对后提交。':'当前环节：'+(labels[x.state]||'待确认')+'。确认后进入'+(next[x.state]||'下一环节')+'。';
 formModal(title,`<div class="detail-action-context"><span>本次办理考核</span><strong>${esc(d.teacher?.name||'当前教师')} · ${esc(d.period?.name||'当前周期')}</strong><p>当前环节：${esc(labels[x.state]||'待核对')} · ${number(x.score,2)} 分</p></div>`+note(hint)+(action==='return'?reasonFields('','退回原因（教师会看到，写清要核对什么）'):reasonFields(action==='archive'?'考核结果核对无误，归档':x.state==='TEACHER'?'已核对本人考核结果，确认无误':'考核结果核对无误，确认提交')),async v=>{
  try{await api('/assessments/'+id+'/actions',{method:'POST',body:{...v,expected_version:x.version,action}})}
  catch(error){
   if(['confirm','archive'].includes(action)&&/计算依据已变化/.test(error.message)){await showAssessment(id);return}
   if(['confirm','archive'].includes(action)&&/未解决.*核对/.test(error.message)){
    const latest=await api('/assessments/'+id);
    if(latest.confirmation_blockers?.count){await showAssessmentBlockers(id);return}
   }
   throw error;
  }
  closeModal();if(queued){await renderKeep();toast(title+'已办理，已打开下一条，请核对后再办理');await openNext(queued);return}await render();await showAssessment(id);
 },{submit:queued?title+'并查看下一条':title,contextLabel:me.role.kind==='teacher'?'三级考核管理 / 本人确认':['dept','college'].includes(me.role.kind)?'教师考核 / 本级办理':'',returnTo:()=>showAssessment(id)});
}
