async function disputeSourceSummaries(items){
 const sources=new Map(),requests=new Map();
 // shortcut: 复用已授权的详情接口，当前列表固定20条；扩大分页时改为服务端批量摘要。
 for(const item of items){const key=item.object_type+'|'+item.object_id;if(requests.has(key))continue;
  const spec={record:['records','records.read'],points:['points','points.read'],assessment:['assessments','assessment.read']}[item.object_type];
  if(!spec||!item.object_id||!can(spec[1]))continue;
  requests.set(key,api('/'+spec[0]+'/'+encodeURIComponent(item.object_id)).then(data=>{
   const x=item.object_type==='record'?data.record:item.object_type==='assessment'?data.assessment:data;if(!x)return;
   const title=item.object_type==='record'?x.project:item.object_type==='points'?pointLabel(x):(data.period?.name||periodName(x.period_id))+' · 本人考核';
   const summary=item.object_type==='record'?`${x.event_date} · ${number(x.hours,2)} 学时 · ${number(x.participants)} 人次 · 归属培训收入 ${number(x.income,2)} 元`:item.object_type==='points'?`${number(x.amount,2)} 分 · ${periodName(x.period_id)}`:`${number(x.score,2)} 分 · ${labels[x.state]||'状态待核实'}`;
   if(title)sources.set(key,{title,summary});
  }).catch(()=>{}));
 }
 await Promise.all(requests.values());return sources;
}
