function customSettingFields(kind,v={}){return field('name','名称','text',v.name||'',{full:true})+(kind==='dict'?field('items','字典项（每行一项）','textarea',(v.items||[]).join('\n'),{full:true}):(v.type?`<div class="form-field"><label>参数类型</label><input value="${esc(paramTypeNames[v.type])}" readonly></div>`:field('type','参数类型','select','text',{options:Object.entries(paramTypeNames)}))+field('value','参数值','text',v.value===undefined?'':v.type==='bool'?(v.value?'是':'否'):String(v.value),{hint:'是/否类型填写“是”或“否”；数值类型填写数字。'}))+field('description','用途说明','textarea',v.description||'',{full:true,required:false})}
function customSettingValue(kind,raw,type){const out={name:String(raw.name||'').trim()};if(raw.description&&String(raw.description).trim())out.description=String(raw.description).trim();if(kind==='dict'){out.items=String(raw.items||'').split('\n').map(s=>s.trim()).filter(Boolean);return out}const t=type||raw.type,text=String(raw.value??'').trim();out.type=t;if(t==='int'){if(!/^-?\d+$/.test(text))throw Error('整数参数请填写整数');out.value=Number(text)}else if(t==='bool'){if(!['是','否'].includes(text))throw Error('是/否参数请填写“是”或“否”');out.value=text==='是'}else out.value=text;return out}
