 if(key==='business_dictionary')body=field('notice_categories','通知分类（每行一项）','textarea',x.value.notice_categories.join('\n'),{full:true})+field('record_sources','来源说明字典（每行一项）','textarea',x.value.record_sources.join('\n'),{full:true})+`<div class="form-field full"><label>状态显示名称</label><div class="status-label-editor">${Object.entries(x.value.status_labels).map(([key,value])=>`<label><span>${esc(defaultStatusLabels[key]||'业务状态')}</span><input data-status-key="${esc(key)}" value="${esc(value)}" required maxlength="60" aria-label="${esc(defaultStatusLabels[key]||'业务状态')}的显示名称"></label>`).join('')}</div><p class="hint">只调整中文显示名称；不能新增、删除状态码或改变流程。</p></div>`;
