function mergeFormChanges(original,before,after){
 if(JSON.stringify(before)===JSON.stringify(after))return original;
 if(original===undefined||after===null||typeof after!=='object'||Array.isArray(after))return after;
 const result={...original};
 for(const key of new Set([...Object.keys(before||{}),...Object.keys(after)])){
  if(!(key in after)){if(key in (before||{}))delete result[key];continue;}
  const value=mergeFormChanges(original?.[key],before?.[key],after[key]);
  if(value===undefined)delete result[key];else result[key]=value;
 }
 return result;
}
