 el.innerHTML=`<h1>组织考核结果 · ${d.immutable?'归档件':'过程稿（非最终结果）'}</h1><p>组织：${esc(d.target.name)}　周期：${esc(d.period.name||periodName(x.period_id))}</p><p>规则：${esc(d.rule.name)} · 版本 ${esc(d.rule.version_no)}　总分：${number(x.score,2)}　状态：${esc(labels[x.state]||x.state)}</p><table><thead><tr><th>指标</th><th>原始值 / 目标值</th><th>权重</th><th>计算过程</th><th>得分</th></tr></thead><tbody>${d.evidence.map(e=>`<tr><td>${esc(e.metric_name)}</td><td>${esc(e.raw_value)} / ${esc(e.target_value)}</td><td>${esc(e.weight)}</td><td>${esc(businessFormula(e.formula))}</td><td>${esc(e.calculated_score)}</td></tr>`).join('')}</tbody></table><p>归档校验：${esc(x.archive_sha256||'未归档，不替代最终确认结果')}</p><p>编号：${esc(x.id)}　打印人：${esc(me.user.name)}　时间：${new Date().toLocaleString('zh-CN')}</p>`;
 document.body.append(el);document.body.classList.add('print-mode');try{window.print()}finally{document.body.classList.remove('print-mode')}
