 return `<section class="connection-overview-head"><div class="overview-interface"><span class="connector-icon ${m.color}">${icon(m.symbol)}</span><div><strong>${esc(m.title)}</strong><small>${esc(m.direction)}</small><p>${esc(c.config?.owner||'责任单位尚未登记')}</p></div></div><div class="connection-overview-stats"><span>资料 <b>${readiness.done} / ${readiness.total}</b></span><span>字段 <b>${readiness.mapCount} / ${entry.data_types.length}</b></span><span>规则 <b>${readiness.ruleCount} / ${entry.data_types.length}</b></span>${badge(c.state)}</div><div class="overview-actions">${admin?act('填写基础资料','connection',c.id,'primary','edit'):''}${admin?act('验证与启用','connection-proof',c.id,'','shield'):''}</div></section><div class="connection-banner"><strong>${c.state==='CONNECTED'?'真实连接证明有效':'当前待对接'}。</strong> ${esc(pendingText)}</div>${integrationMaterialPanel(entry)}<section class="card mt16 integration-type-overview"><div class="card-head"><div><h2>${c.code==='sso'?'身份规则一览':'业务接口规则一览'}</h2><p>所有业务类型放在一张表中，直接看哪一类还缺字段或接口规则。</p></div><span class="subtle">${entry.data_types.length} 类</span></div>${table(['业务类型','本地准备情况','字段对应','接口规则','操作'],rows)}<div class="card-foot">保存资料和本地校验都不等于真实联调通过；真实结果以学校系统及省平台回执为准。</div></section>`+(c.code!=='sso'&&me.role.kind==='school'?latestSyncHTML(entry,summary):'');
