async function submitCxClaim(login,note=''){
 const r=await api('/reference/cx-claims',{method:'POST',body:{login,note}});
 toast(r.state==='APPROVED'?`已认领，${r.moved} 门超星课已算到你名下`:'已提交，等学校系统管理员确认后生效');
 if(page==='home')await render();
 await showCxClaim();
}
