const auditModuleNames={access:'业务访问',auth:'账号登录',users:'账号管理',roles:'角色授权',organizations:'组织机构',settings:'基础配置',rules:'教师规则',organization_rules:'组织考核规则',records:'培训台账',participations:'教师参训',qualifications:'教师资质',points:'教师积分',assessments:'教师考核',organization_assessments:'组织考核',disputes:'数据核对',notices:'政策通知',attachments:'业务附件',exports:'报表导出',imports:'表格导入',tasks:'后台任务',periods:'考核周期'};
const auditModuleName=key=>auditModuleNames[key]||auditModuleNames[key+'s']||({social_project:'培训项目',social_resource:'培训资源与更正',social_claim:'积分认定',social_annual:'学院年度考核',social_policy:'制度口径'}[key])||'其他业务';
function auditActionName(action){return ({GET:'查询业务',POST:'提交办理',PUT:'更新业务',DELETE:'移除关联',PATCH:'调整业务'}[action])||(/[\u4e00-\u9fff]/.test(action||'')?action:'业务操作')}
function auditBusinessSnapshot(value){
 if(!value||!Object.keys(value).length)return '<p class="muted">无业务变更</p>';
 const names={...evidenceNames,authorization_pending:'授权待确认',value:'配置内容',school_name:'学校名称',expiry_days:'提前提醒天数',categories:'资质类别',notice_categories:'通知分类',record_sources:'数据来源',status_labels:'状态名称',max_rows:'单批导入行数',income_note:'收入口径',participants_note:'人次口径',permissions:'授权项目',active:'是否启用',published:'是否发布',title:'标题',body:'正文',category:'分类',version:'数据版本',resolution:'复核结论',http_status:'响应状态',elapsed_ms:'处理耗时（毫秒）',expected_version:'操作前版本',confirmed:'是否确认'};
 function renderValue(v,key='',depth=0){if(depth>6)return '详见业务记录';if(v==null)return '未填写';if(Array.isArray(v))return v.map(x=>renderValue(x,key,depth+1)).join('、')||'无';if(typeof v==='object'){const rows=Object.entries(v).filter(([k])=>names[k]||(key==='status_labels'&&labels[k]));return rows.length?'<dl class="kv">'+rows.map(([k,x])=>'<dt>'+esc(key==='status_labels'?labels[k]:names[k])+'</dt><dd>'+renderValue(x,k,depth+1)+'</dd>').join('')+'</dl>':'关联记录已留存，请从对应业务查看详情。'}if(typeof v==='boolean')return v?'是':'否';if(key==='created_at')return esc(ts(v));if(key==='permissions')return esc(permLabels[v]||'其他授权项目');if(key==='state')return esc(labels[v]||'状态待核实');return esc(evidenceNames[v]||v)}
 return renderValue(value);
}
function openPortalSearch(){
 modal('搜索菜单与业务',`<form id="portal-search-form" class="filterbar"><input id="menu-search" aria-label="搜索菜单与业务" maxlength="100" placeholder="输入项目、课程、证书或通知关键词" autocomplete="off"><button class="btn primary">搜索业务</button></form><h3>菜单入口</h3><div id="menu-results" class="search-results">${navItems().flatMap(x=>x[1]).map(([p,i])=>`<button data-action="search-nav" data-id="${p}" data-alias="${esc((navAliases[p]||[]).join(' '))}">${icon(i)}${esc(navLabel(p))}</button>`).join('')}</div><div id="business-search-results" aria-live="polite">${note('输入关键词后点击“搜索业务”，仅查询当前账号有权查看的内容。')}</div>`,act('关闭','close'),true);
 const input=$('#menu-search'),target=$('#business-search-results'),form=$('#portal-search-form');
 input.addEventListener('input',()=>$$('#menu-results button').forEach(x=>x.hidden=!(x.textContent+' '+(x.dataset.alias||'')).includes(input.value.trim())));
 let seq=0;
 form.addEventListener('submit',async event=>{event.preventDefault();const word=input.value.trim();const current=++seq;if(!word){target.innerHTML=note('请输入搜索关键词');return}target.innerHTML=note('正在搜索授权业务…');
 try{const data=await api('/portal/search?'+query({q:word}));if(current!==seq||$('#business-search-results')!==target)return;
 target.innerHTML=data.groups.some(g=>g.items.length)?data.groups.filter(g=>g.items.length).map(g=>`<section class="mt20"><h3>${esc(g.title)}</h3>${table(['业务名称','说明','操作'],g.items.map(x=>[esc(x.title),esc(x.description)+(x.state?' · '+esc(labels[x.state]||'状态待核实'):''),act('查看详情',g.type==='notice'?'notice':'todo',g.type==='notice'?x.id:g.type+'|'+x.id,'sm')]))}${g.has_more?'<p class="hint">本类显示前 10 条，请缩小关键词或进入业务页继续筛选。</p>':''}</section>`).join(''):empty('没有找到匹配业务','请更换关键词，或通过上方菜单进入对应业务。');
 }catch(error){if(current===seq&&$('#business-search-results')===target)target.innerHTML=note(error.message,true)}});
}
