for(const action of ['impl-draft-diff','impl-quick-trial','impl-quick-publish','impl-quick-disable','impl-step','impl-handover','impl-copy','impl-materials','impl-credential-meta','impl-acceptance','impl-probe','impl-publish','impl-health','impl-reset','impl-login-test'])handlers[action]=id=>handleImplementationAction(action,id,implementationContext());
document.addEventListener('submit',async e=>{if(e.target.id!=='lib-filters')return;e.preventDefault();libraryFilterSubmit(e.target);try{await render()}catch(err){toast(err.message,true)}});
document.addEventListener('submit',async e=>{if(e.target.id!=='social-search-form')return;e.preventDefault();try{if(e.target.classList.contains('tw-filters')){const v=Object.fromEntries(new FormData(e.target));trainingChange(page,socialContext(),'filter',{q:v.q||'',org:v.org||'',package:v.package==='on',oneSkill:v.oneSkill==='on'});if(page==='trainers'){await render();return}}await socialAction('social-list-apply','',socialContext())}catch(err){toast(err.message,true)}});
document.addEventListener('click',e=>{for(const d of $$('.more-actions[open]'))if(!d.contains(e.target)||e.target.closest('.more-actions-menu [data-action],.more-actions-menu a'))d.open=false});
document.addEventListener('click',e=>{const menu=$('#account-menu');if(menu?.open&&(!menu.contains(e.target)||e.target.closest('[data-action]')))menu.open=false});
document.addEventListener('keydown',e=>{const menu=$('#account-menu');if(e.key==='Escape'&&menu?.open){menu.open=false;$('summary',menu)?.focus();e.stopImmediatePropagation()}},true);
if(typeof window.addEventListener==='function')window.addEventListener('focus',()=>{if(me)refreshAccountSummary()});
document.addEventListener('click',async e=>{const target=e.target.closest('[data-action]');if(!target||target.disabled)return;const fn=handlers[target.dataset.action];if(!fn){toast('此操作入口暂不可用',true);return}actionTrigger=target;captureQueue(target);target.disabled=true;try{await fn(target.dataset.id,target)}catch(err){toast(err.message,true)}finally{if(target.isConnected)target.disabled=false;actionTrigger=null}});
let lookupTimer;document.addEventListener('input',e=>{const input=e.target;if(!input.matches('.teacher-lookup,.filter-teacher'))return;clearTimeout(lookupTimer);lookupTimer=setTimeout(async()=>{try{const d=await api('/teachers?'+query({q:input.value,size:50}));for(const t of d.items)if(!teachers.find(x=>x.id===t.id))teachers.push(t);const list=document.getElementById(input.getAttribute('list'));if(list)list.innerHTML=d.items.map(t=>`<option value="${esc(t.staff_no)}">${esc(t.name)}</option>`).join('');const chosen=teachers.find(t=>t.staff_no===input.value);if(input.matches('.teacher-lookup')){const hidden=input.parentElement.querySelector('input[type=hidden]');if(hidden)hidden.value=chosen?.id||''}}catch(err){toast(err.message,true)}},280)});
document.addEventListener('change',e=>{if(e.target.matches('.teacher-lookup')){const input=e.target,t=teachers.find(x=>x.staff_no===input.value);input.parentElement.querySelector('input[type=hidden]').value=t?.id||''}});
document.addEventListener('keydown',async e=>{if(e.key!=='Enter'||e.target.id!=='social-project-query')return;e.preventDefault();try{await socialAction('social-project-lookup','1',socialContext())}catch(err){toast(err.message,true)}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('#sidebar')?.classList.contains('open'))setMobileMenu(false,true);else if(!me?.user.must_change_password)closeModal()}if(e.key==='/'&&!e.target.matches('input,textarea,select')&&me){e.preventDefault();handlers.search()}});
document.addEventListener('keydown',e=>{if(e.key!=='Tab'||$('#modal-root').classList.contains('hidden'))return;const nodes=$$('button:not([disabled]),input:not([type=hidden]):not([disabled]),select:not([disabled]),textarea:not([disabled]),a[href],[tabindex="0"]',$('#modal-root')).filter(x=>x.getClientRects().length);const first=nodes[0],last=nodes.at(-1);if(!first)return;if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}});
window.addEventListener('resize',()=>{if(me)syncMenuAccessibility()});
window.addEventListener('hashchange',()=>{if(!me)return;try{const next=restoreNavigation(location.hash,titles);if(navigationHash(next.page,next.filter,next.periodId)===navigationHash(page,filter,periodId))return;page=routeAlias(next.page);filter=next.filter;periodId=next.periodId;tablePage=1;participationPage=1;render()}catch(err){toast(err.message,true)}});
window.addEventListener('afterprint',()=>document.body.classList.remove('print-mode'));
(async()=>{try{await boot()}catch{if(!me)loginView()}})();

